/**
 * 사업자등록번호(10자리)의 가운데 2자리로 개인사업자 여부를 판별한다.
 * 01~79 과세, 80 다단계판매원, 89 법인 아닌 종교단체, 90~99 면세가 개인에 해당한다.
 * (81~88 은 영리/비영리 법인, 국가·지자체, 외국법인)
 */
export const isPersonalBizNo = (bizNo?: string | null): boolean => {
  const digits = (bizNo ?? '').replace(/[^0-9]/g, '');
  if (digits.length !== 10) return false;

  const mid = Number(digits.substring(3, 5));

  return (mid >= 1 && mid <= 80) || mid === 89 || (mid >= 90 && mid <= 99);
};
